krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *hostname = NULL;
    kdc_realm_t *referral_realm = NULL;
    krb5_principal *princ = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_ERR_GENERIC;
    }

    if (!request->server) {
        return KRB5KDC_ERR_NOPOLICY;
    }

    hostname = krb5_principal_get_realm(request->server);
    if (!hostname || hostname->length == 0) {
        return KRB5KDC_ERR_GENERIC;
    }

    ret = kdc_realm_find_by_realm(kdc_active_realm->context, hostname, &referral_realm);
    if (ret != 0 || !referral_realm) {
        return KRB5KDC_ERR_REALM_NOT_FOUND;
    }

    ret = krb5_build_principal(request->context, &princ, hostname->length, hostname->data, strlen("krbtgt"),
                                 "krbtgt", referral_realm->realm->length, referral_realm->realm->data, NULL);
    if (ret != 0) {
        goto cleanup;
    }

    *krbtgt_princ = princ;

cleanup:
    if (hostname) {
        krb5_free_data(request->context, hostname);
    }

    if (referral_realm) {
        kdc_realm_free(referral_realm);
    }

    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_int32 retval = KRB5_KDC_ERR_REALM_UNKNOWN;
    krb5_principal *server_princ = NULL;
    krb5_data *hostname = NULL;
    kdc_realm_t *referral_realm = NULL;

    if (request->server == NULL)
        goto cleanup;

    server_princ = request->server;

    hostname = krb5_principal_get_realm(server_princ);
    if (hostname == NULL)
        goto cleanup;

    referral_realm = find_realm_by_name(kdc_active_realm, hostname);
    if (referral_realm == NULL)
        goto cleanup;

    if (referral_realm->realm == NULL || referral_realm->realm->length == 0)
        goto cleanup;

    *krbtgt_princ = krb5_build_principal_from_name(kdc_active_realm->context,
                                                     referral_realm->realm,
                                                     "krbtgt",
                                                     referral_realm->realm,
                                                     NULL);

    if (*krbtgt_princ == NULL) {
        retval = KRB5_KDC_ERR_KDC_NOT_REACHABLE;
        goto cleanup;
    }

    retval = 0; /* Success */

cleanup:
    if (hostname)
        krb5_free_data(kdc_active_realm->context, hostname);
    return retval;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_error_code ret = KRB5KDC_ERR_NONE;
    krb5_data *hostname = NULL;
    krb5_realm *target_realm = NULL;
    krb5_principal tgs_princ = NULL;

    /* Check if the request is a referral request (e.g., is_referral flag or specific request type) */
    if (!request->is_referral) {
        return KRB5KDC_ERR_POLICY;
    }

    /* Extract the hostname from the server principal */
    ret = extract_hostname_from_principal(request->client, &hostname);
    if (ret != 0) {
        return ret;
    }

    /* Verify that the hostname is a valid FQDN */
    if (!is_valid_fqdn(hostname)) {
        ret = KRB5KRB_AP_ERR_MODIFIED;
        goto cleanup;
    }

    /* Find the realm associated with the hostname */
    target_realm = find_realm_by_hostname(hostname);
    if (target_realm == NULL) {
        ret = KRB5_REALM_CANT_RESOLVE;
        goto cleanup;
    }

    /* Ensure the realm is valid and not empty */
    if (target_realm->realm_data.length == 0) {
        ret = KRB5_REALM_CANT_RESOLVE;
        goto cleanup;
    }

    /* Construct the TGT principal in the target realm */
    ret = krb5_build_principal(kdc_active_realm->context, &tgs_princ, target_realm->realm_data.length,
                               target_realm->realm_data.data, "krbtgt", hostname->length, hostname->data, NULL);
    if (ret != 0) {
        goto cleanup;
    }

    *krbtgt_princ = tgs_princ;

cleanup:
    if (hostname) {
        krb5_data_free(hostname);
    }
    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = KRB5KDC_ERR_UNKNOWN;
    krb5_data *hostname = NULL;
    krb5_realm *target_realm = NULL;
    krb5_principal tgs_princ = NULL;

    if (!request || !krbtgt_princ || !kdc_active_realm)
        return KRB5KDC_ERR_BADOPTION;

    if (request->alternative_targets == NULL || request->alternative_targets->length <= 0)
        return KRB5KDC_ERR_BADOPTION;

    hostname = &request->alternative_targets->data[0];
    if (!hostname->length || !krb5_is_fqdn(krb5_context, hostname->data)) {
        ret = KRB5KDC_ERR_BAD_TARG_NAME;
        goto cleanup;
    }

    ret = krb5_kdc_realm_get_by_name(krb5_context, hostname->data, &target_realm);
    if (ret != 0 || !target_realm || target_realm[0].length == 0)
        goto cleanup;

    ret = krb5_build_principal(krb5_context, &tgs_princ, target_realm[0].length, target_realm[0].data, 8, "krbtgt", target_realm[0].data, NULL);
    if (ret != 0)
        goto cleanup;

    *krbtgt_princ = tgs_princ;
    ret = 0;

cleanup:
    if (hostname)
        krb5_data_free(hostname);
    if (target_realm)
        krb5_free_realm(krb5_context, target_realm);
    if (ret != 0 && tgs_princ)
        krb5_free_principal(krb5_context, tgs_princ);

    return ret;
}

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal **krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *hostname = NULL;
    krb5_realm *target_realm = NULL;
    krb5_principal tgs_princ = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_ERR_BADOPTION;
    }

    if (request->kdc_options & KDC_OPT_REFERRAL) {
        hostname = krb5_unparse_name(request->server);
        if (!hostname) {
            return KRB5KDC_ERR_NAME_EXP;
        }

        if (!krb5_is_fqdn(hostname->data)) {
            krb5_data_free(hostname);
            return KRB5KDC_ERR_NAME_EXP;
        }

        target_realm = krb5_find_realm_by_host(hostname->data);
        if (!target_realm) {
            krb5_data_free(hostname);
            return KRB5KDC_ERR_REALM_NOT_FOUND;
        }

        if (!target_realm->name || !target_realm->name->data || !target_realm->name->length) {
            krb5_data_free(hostname);
            return KRB5KDC_ERR_REALM_EMPTY;
        }

        ret = krb5_build_principal_simple(&tgs_princ, target_realm->name->data,
                                          strlen("krbtgt"), "krbtgt",
                                          strlen(kdc_active_realm->realm->data), kdc_active_realm->realm->data);
        if (ret != 0) {
            krb5_data_free(hostname);
            return ret;
        }

        *krbtgt_princ = tgs_princ;
    }

    if (hostname) {
        krb5_data_free(hostname);
    }

    return ret;
}
